// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 betAmount) public {
        betAmount = bound(betAmount, 1, type(uint256).max);
        vm.assume(address(c).balance >= 0);

        // Open to public and set bet limit
        c.OpenToThePublic();
        c.AdjustBetAmounts(betAmount);

        // Prepare caller with enough ETH
        address player = address(0x1234);
        vm.deal(player, betAmount);
        vm.prank(player, player);

        // Call wager with the exact bet amount
        c.wager{value: betAmount}();

        // Assert that the player's wager is correctly recorded
        assertTrue(c.hasPlayerWagered(player));
    }
}

